mapper.select:
SELECT page.account_bucket_key AS bucketKey, page.account_id AS accountId, usage.account_phone_snapshot AS senderPhone, usage.sender_country_iso2_snapshot AS senderCountryIso2, usage.account_type_snapshot AS accountTypeCode, usage.account_created_at_snapshot AS accountCreatedAt, page.send_total AS sendTotal, page.success_num AS successNum, page.delivered_num AS deliveredNum, page.failed_num AS failedNum, page.last_send_at AS lastSendAt FROM ( SELECT grouped.* FROM (
) grouped WHERE
LIMIT #{criteria.pageSize} OFFSET #{criteria.offset} ) page LEFT JOIN hyperlink_task_account_usage usage ON usage.hyperlink_task_id = #{criteria.taskId} AND usage.account_id = page.account_id

SELECT * FROM hyperlink_task_recipient
WHERE short_code=#{shortCode}
FOR UPDATE

SELECT visit.bucket_no, COUNT(*) AS new_uv
FROM (
  SELECT FLOOR((first_visit_at-#{anchorAt})/#{bucketMs}) AS bucket_no
  FROM hyperlink_task_recipient
  WHERE hyperlink_task_id=#{taskId} AND first_visit_at>=#{anchorAt}
    AND first_visit_at<#{endAt}
) visit
GROUP BY visit.bucket_no
ORDER BY bucket_no

SELECT id, tenant_id, first_visit_at FROM hyperlink_task_recipient
WHERE first_visit_at<#{cutoffAt} AND attribution_purged_at IS NULL
ORDER BY first_visit_at, id LIMIT #{limit}

mapper.update:
UPDATE hyperlink_task_recipient SET first_visit_ip_address=NULL,
  first_visit_user_agent=NULL, first_visit_browser=NULL, first_visit_os=NULL,
  first_visit_device=NULL, first_visit_language=NULL, first_visit_country_iso2=NULL,
  attribution_purged_at=#{purgedAt}, updated_at=#{purgedAt}
WHERE tenant_id=#{tenantId} AND id=#{id} AND first_visit_at<#{cutoffAt}
  AND attribution_purged_at IS NULL

