SELECT id, tenant_id, hyperlink_task_id, hyperlink_task_round_id, account_id, send_status, metrics_projected_status, submitted_at, metrics_projected_at FROM hyperlink_task_recipient WHERE needs_metrics_projection=1 AND id IN
#{id}
ORDER BY tenant_id, hyperlink_task_id, updated_at, id FOR UPDATE SKIP LOCKED

SELECT * FROM hyperlink_task_recipient
WHERE tenant_id=#{tenantId} AND hyperlink_task_id=#{taskId}
  AND id=#{recipientId} AND command_id=#{commandId} FOR UPDATE

SELECT * FROM hyperlink_task_recipient
WHERE tenant_id=#{tenantId} AND hyperlink_task_id=#{taskId}
  AND send_status=1 AND command_id IS NULL
  AND hyperlink_task_round_id IS NULL AND next_dispatch_at<=#{now}
ORDER BY id LIMIT 1 FOR UPDATE SKIP LOCKED

