UPDATE hyperlink_task_recipient SET send_status=6, fail_code='TASK_STOPPED',
  fail_reason='任务已停止', failed_at=#{now}, updated_at=#{now}
WHERE hyperlink_task_id=#{taskId} AND command_id IS NULL AND send_status=1
  AND id IN

    #{id}

UPDATE hyperlink_task_recipient SET metrics_projected_status=send_status,
  metrics_projected_at=#{now}, updated_at=#{now}
WHERE hyperlink_task_id=#{taskId} AND metrics_projected_status<>send_status

UPDATE hyperlink_task_recipient SET metrics_projected_status=send_status,
  metrics_projected_at=#{now}, updated_at=#{now}
WHERE needs_metrics_projection=1 AND id IN

  #{id}

UPDATE hyperlink_task_recipient SET send_status=6, fail_code=#{failCode},
  fail_reason=#{failReason}, failed_at=#{now}, updated_at=#{now}
WHERE hyperlink_task_id=#{taskId} AND send_status=1
  AND command_id IS NULL AND hyperlink_task_round_id IS NULL
ORDER BY id LIMIT #{limit}

mapper.select:
SELECT tenant_id, hyperlink_task_id AS task_id, id AS recipient_id,
  account_id, command_id, protocol_backend, submitted_at
FROM hyperlink_task_recipient
WHERE send_status=2 AND command_id IS NOT NULL AND next_dispatch_at<=#{now}
ORDER BY next_dispatch_at, id LIMIT #{limit}
